SET @found = (SELECT COUNT(*) FROM `entity_versions` WHERE `locale` IS NULL AND (`entity_key` = 'chapter:catpope:4' OR `entity_key` LIKE 'scene:catpope:4:%') AND `json` LIKE '%"type":"unlockLocation","params":{"location":"well"}%' AND (`id` IN (SELECT MAX(`id`) FROM `entity_versions` WHERE `locale` IS NULL AND (`entity_key` = 'chapter:catpope:4' OR `entity_key` LIKE 'scene:catpope:4:%') GROUP BY `entity_key`) OR `id` IN (SELECT MAX(`id`) FROM `entity_versions` WHERE `locale` IS NULL AND `status` = 'published' AND (`entity_key` = 'chapter:catpope:4' OR `entity_key` LIKE 'scene:catpope:4:%') GROUP BY `entity_key`)));
UPDATE `entity_versions` SET `json` = JSON_COMPACT(IF(JSON_EXISTS(`json`, CONCAT('$.groups[0].slices[0]', '.events')), JSON_ARRAY_APPEND(`json`, CONCAT('$.groups[0].slices[0]', '.events'), JSON_EXTRACT(@event, '$')), JSON_INSERT(`json`, CONCAT('$.groups[0].slices[0]', '.events'), JSON_ARRAY(JSON_EXTRACT(@event, '$'))))) WHERE @found = 0 AND `entity_key` = 'chapter:catpope:4' AND `locale` IS NULL AND JSON_EXISTS(`json`, '$.groups[0].slices[0]') AND `json` NOT LIKE '%"type":"unlockLocation","params":{"location":"well"}%';
